css:
.dcx{ -webkit-text-size-adjust: 100%; }
.dcx{ margin: 0; background: #fff; color: #0A1330; font-family: 'Instrument Sans', system-ui, sans-serif; -webkit-font-smoothing: antialiased; overflow-x:clip; }
.dcx *{ box-sizing: border-box; }
.dcx h1,.dcx h2,.dcx h3,.dcx h4{ margin: 0; font-family: 'Source Serif 4', Georgia, serif; font-weight: 700; letter-spacing: -0.015em; }
.dcx p{ margin: 0; text-wrap: pretty; }
.dcx a{ color: #0E8C46; text-decoration: none; }
.dcx a:hover{ color: #15A857; }
.dcx :focus-visible{ outline: 2px solid #15A857; outline-offset: 3px; border-radius: 4px; }
.dcx [data-burger]{ display: none; }
@media (max-width: 1100px){.dcx [data-navlinks],.dcx [data-navlogin]{ display: none !important; }
.dcx [data-burger]{ display: inline-flex !important; }
.dcx [data-hero],.dcx [data-signals],.dcx [data-symptoms],.dcx [data-healthy],.dcx [data-plan],.dcx [data-trend],.dcx [data-industries]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-sgrid],.dcx [data-dials]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-eco]{ grid-template-columns: repeat(4, minmax(0,1fr)) !important; }
.dcx [data-cta-row]{ grid-template-columns: minmax(0,1fr) !important; justify-items: start !important; }
.dcx [data-h1]{ font-size: 36px !important; }
.dcx [data-h2]{ font-size: 26px !important; }
}
@media (max-width: 700px){.dcx [data-sgrid],.dcx [data-dials],.dcx [data-eco],.dcx [data-cta-row]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-h1]{ font-size: 30px !important; }
.dcx [data-pad]{ padding-left: 20px !important; padding-right: 20px !important; }
}
